//
// Catalog model mirroring crates/nexttouch-catalog (schema
// "nexttouch-catalog/1"). The bundled catalog.json is generated by
// tools/gen_catalog.py from ipsw.me and shipped identically on all
// platforms.
//
// Honesty rule: status is only tested/tested_slow/experimental for the
// legacy range the baseline engine implements. Every iOS 8/9/10 entry is
// notBootingYet in v0.1.0 — the picker must never claim one boots.

import Foundation

enum FirmwareStatus: String, Codable {
    case tested = "tested"
    case testedSlow = "tested_slow"
    case experimental = "experimental"
    case notBootingYet = "not_booting_yet"

    var label: String {
        switch self {
        case .tested: return "Tested"
        case .testedSlow: return "Tested, slow"
        case .experimental: return "Experimental"
        case .notBootingYet: return "Not booting yet"
        }
    }

    var isRunnable: Bool { self != .notBootingYet }
}

enum DeviceTier: String, Codable {
    case legacy
    case target
    case experimental
    case future

    var label: String {
        switch self {
        case .legacy: return "Legacy (engine-supported)"
        case .target: return "Target (A5 — in development)"
        case .experimental: return "Experimental (A6 — planned)"
        case .future: return "Future (arm64 — planned)"
        }
    }
}

/// Internal engineering stage ladder (planned -> skeleton -> kernel ->
/// userland -> springboard -> usable -> qualified). iOS 8/9/10 entries
/// are all .planned in v0.1.0; see docs/ROADMAP.md for the M1–M6 boot
/// milestones a stage claim must be backed by.
enum Stage: String, Codable {
    case planned
    case skeleton
    case kernel
    case userland
    case springboard
    case usable
    case qualified
}

struct FirmwareEntry: Codable, Identifiable, Hashable {
    let id: String?
    let version: String?
    let build: String?
    let osName: String?
    let iosMajor: Int?
    let ipswFilename: String?
    let downloadURL: String?
    let sha256: String?
    let sha256Note: String?
    let signed: Bool?
    let status: FirmwareStatus
    let stage: Stage

    enum CodingKeys: String, CodingKey {
        case id, version, build, signed, status, sha256, stage
        case osName = "os_name"
        case iosMajor = "ios_major"
        case ipswFilename = "ipsw_filename"
        case downloadURL = "download_url"
        case sha256Note = "sha256_note"
    }

    // Identifiable: catalog id when present, else a composite placeholder.
    var listID: String { id ?? "unconfirmed-\(iosMajor ?? 0)" }
}

struct Device: Codable, Identifiable, Hashable {
    let identifier: String
    let name: String
    let board: String
    let soc: String
    let socChip: String
    let arch: String
    let displayPx: [Int]
    let ramMB: Int
    let tier: DeviceTier
    let quickStart: Bool
    let firmwares: [FirmwareEntry]

    var id: String { identifier }

    enum CodingKeys: String, CodingKey {
        case identifier, name, board, soc, arch, tier, firmwares
        case socChip = "soc_chip"
        case displayPx = "display_px"
        case ramMB = "ram_mb"
        case quickStart = "quick_start"
    }
}

struct Catalog: Codable {
    let schema: String
    let catalogVersion: Int
    let generatedAtUTC: String
    let generatedBy: String
    let source: String
    let verified: Bool
    let quickStart: [String]
    let devices: [Device]

    enum CodingKeys: String, CodingKey {
        case schema, source, verified, devices
        case catalogVersion = "catalog_version"
        case generatedAtUTC = "generated_at_utc"
        case generatedBy = "generated_by"
        case quickStart = "quick_start"
    }

    func device(_ identifier: String) -> Device? {
        devices.first { $0.identifier == identifier }
    }

    func search(_ query: String) -> [Device] {
        let q = query.trimmingCharacters(in: .whitespaces).lowercased()
        if q.isEmpty { return devices }
        return devices.filter {
            $0.name.lowercased().contains(q)
                || $0.identifier.lowercased().contains(q)
                || $0.board.contains(q)
                || $0.soc.lowercased().contains(q)
                || $0.socChip.lowercased().contains(q)
        }
    }

    static func loadBundled() -> Catalog {
        guard let url = Bundle.main.url(forResource: "catalog", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let catalog = try? JSONDecoder().decode(Catalog.self, from: data)
        else {
            // The catalog is a build-time asset; failing to load it is a
            // packaging bug, surfaced as an empty catalog rather than a crash.
            return Catalog(schema: "nexttouch-catalog/1", catalogVersion: 0,
                           generatedAtUTC: "", generatedBy: "", source: "",
                           verified: false, quickStart: [], devices: [])
        }
        return catalog
    }
}

/// One device in the user's library. The local id is random — never a
/// guest hardware identifier (privacy audit rule, all platforms).
struct LibraryItem: Codable, Identifiable, Equatable {
    let id: String
    var name: String
    let deviceIdentifier: String
    let firmwareID: String
    let firmwareVersion: String
    var dirty: Bool = false
}
